"""Reviewed query-understanding cases; expectations are not generated by the resolver."""
import argparse
import json
import math
from pathlib import Path
import time
import urllib.request

CASES = [
    ('typo_methods', 'what are the methods to purify coper?', 'Copper', 'Compound', 'compound_methods'),
    ('transpose', 'Which purification methods are used for coppre?', 'Copper', 'Compound', 'compound_methods'),
    ('insertion', 'List purification methods for coppper.', 'Copper', 'Compound', 'compound_methods'),
    ('lead_methods', 'What methods can purify lead?', 'Lead', 'Compound', 'compound_methods'),
    ('method_phrasing', 'Tell me the purification methods used for Copper.', 'Copper', 'Compound', 'compound_methods'),
    ('method_phrasing_heldout', 'For Copper, which methods are recorded?', 'Copper', 'Compound', 'compound_methods'),
    ('symptom_typo', 'What are the symptoms of psoraisis?', 'Psoriasis', 'Disease', 'disease_symptoms'),
    ('symptom_variant', 'Tell me the signs associated with Psoriasis.', 'Psoriasis', 'Disease', 'disease_symptoms'),
    ('exact_indication', 'Which compounds treat Cancer?', 'Cancer', 'Indication', 'indication_compound'),
    ('broad_symptoms', 'What are the symptoms of cancer?', None, None, 'clarify'),
    ('indication_therapy', 'What are the therapies of cancer?', None, None, 'clarify'),
    ('broad_heldout', 'List symptoms associated with malignant neoplasm.', None, None, 'clarify'),
    ('synonym', 'What are the symptoms of esophageal squamous cell cancer?', 'Esophageal Squamous Cell Carcinoma', 'Disease', 'disease_symptoms'),
    ('abbreviation', 'What symptoms are associated with ESCC?', 'Esophageal Squamous Cell Carcinoma', 'Disease', 'disease_symptoms'),
    ('unknown', 'Which symptoms are linked to zzzunknowncondition?', None, None, 'abstain'),
    ('short_uncertain', 'What purifies cop?', None, None, 'abstain'),
]

def request(question, transport, context=None, selection=None):
    payload = dict(question=question, stream=transport == 'sse')
    if context is not None:
        payload['conversation_context'] = context
    if selection is not None:
        payload['selected_entity'] = selection
    req = urllib.request.Request('http://127.0.0.1:8081/api/chatbot_response.php',
        data=json.dumps(payload).encode(), headers={'Content-Type': 'application/json'})
    start = time.perf_counter()
    with urllib.request.urlopen(req, timeout=60) as response:
        text = response.read().decode()
    if transport == 'json':
        result = json.loads(text)
    else:
        result, ctx = {}, {}
        for frame in text.replace('\r\n', '\n').split('\n\n'):
            event = next((x[6:].strip() for x in frame.splitlines() if x.startswith('event:')), '')
            data = '\n'.join(x[5:].strip() for x in frame.splitlines() if x.startswith('data:'))
            if not data:
                continue
            if event == 'context': ctx = json.loads(data)
            if event == 'done': result = json.loads(data)
        result['context'] = ctx
    return result, round((time.perf_counter() - start) * 1000, 2)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    if args.output.exists(): raise SystemExit('Refusing to overwrite report')
    rows = []
    for transport in ['json', 'sse']:
        for case, question, name, node_type, endpoint in CASES:
            result, ms = request(question, transport)
            route = result.get('context', {}).get('routing') or {}
            if endpoint == 'clarify':
                passed = result.get('status') == 'needs_clarification' and bool(result.get('clarification', {}).get('candidates'))
            elif endpoint == 'abstain':
                passed = result.get('status') in ['needs_clarification', 'entity_not_found', 'unsupported']
            else:
                passed = result.get('status') in ['success', 'no_data'] and route.get('entity') == name and route.get('entity_type') == node_type and route.get('endpoint') == endpoint
            rows.append(dict(case=case, question=question, transport=transport, passed=passed, latency_ms=ms, response=result))
    times = sorted(r['latency_ms'] for r in rows)
    report = dict(total=len(rows), passed=sum(r['passed'] for r in rows),
        latency_ms=dict(p50=times[math.ceil(len(times)*.5)-1], p95=times[math.ceil(len(times)*.95)-1]), cases=rows)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(report, indent=2, ensure_ascii=False), encoding='utf-8')
    print(json.dumps({k:v for k,v in report.items() if k != 'cases'}))
    return 0 if report['passed'] == report['total'] else 1

if __name__ == '__main__':
    raise SystemExit(main())
